<?php
/** Public interaction center: Ask questions and contribute knowledge. */
require_once 'config/db.php'; require_once 'config/auth.php'; require_once 'config/csrf.php'; require_once 'config/activity.php';
$msg=''; $err='';
if($_SERVER['REQUEST_METHOD']==='POST'){ try{ verify_csrf(); $action=$_POST['action']??''; $name=trim($_POST['visitor_name']??''); if(mb_strlen($name)<2) throw new RuntimeException('Please enter a name or nickname.');
 if($action==='question'){ $q=trim($_POST['question']??''); if(mb_strlen($q)<5) throw new RuntimeException('Please enter a complete question.'); $pdo->prepare('INSERT INTO Community_questions(visitor_name,question) VALUES(?,?)')->execute([$name,$q]);
 notify_admins($pdo, 'New community question', $name.' submitted a question for the community.', 'community'); $msg='Question submitted. An administrator can answer it for the community.'; }
 elseif($action==='contribution'){ $title=trim($_POST['title']??''); $content=trim($_POST['content']??''); $source=trim($_POST['source']??''); if(mb_strlen($title)<3||mb_strlen($content)<10) throw new RuntimeException('Please provide a title and useful knowledge contribution.'); $image=null; if(!empty($_FILES['image']['name'])){ require_once 'config/upload.php'; $image=save_upload('image',['jpg','jpeg','png','webp'],10000000); } $pdo->prepare('INSERT INTO Knowledge_contributions(visitor_name,title,content,source,image_path) VALUES(?,?,?,?,?)')->execute([$name,$title,$content,$source,$image]);
 notify_admins($pdo, 'New knowledge contribution', $name.' submitted: '.$title, 'community'); $msg='Thank you. Your knowledge contribution is now queued for administrator review.'; }
 }catch(Throwable $e){$err=$e->getMessage();}}
$qs=$pdo->query("SELECT id,visitor_name,question,answer,created_at,answered_at FROM Community_questions WHERE status='answered' ORDER BY answered_at DESC LIMIT 20")->fetchAll();
$contributions=$pdo->query("SELECT id,visitor_name,title,content,source,image_path,reviewed_at FROM Knowledge_contributions WHERE status='approved' ORDER BY reviewed_at DESC,created_at DESC LIMIT 30")->fetchAll();
$title='Community Knowledge'; include 'partials/header.php'; ?>
<div class="page-band"><div><span class="eyebrow">COMMUNITY KNOWLEDGE</span><h1>Ask, Share, and Learn Together</h1><p>Public visitors can ask questions, share knowledge, and read answers without creating an account.</p></div></div>
<?php if($msg): ?><div class="alert success-box">✓ <?=e($msg)?></div><?php endif; ?><?php if($err): ?><div class="alert">⚠ <?=e($err)?></div><?php endif; ?>
<div class="grid2 community-panels"><section class="card"><span class="badge">ASK A POT MAKER</span><h2>❓ Ask a Question</h2><p>Ask about techniques, uses, stories, tools, or traditional practices.</p><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="question"><input class="input" name="visitor_name" required maxlength="120" placeholder="Your name / nickname"><textarea name="question" rows="5" required maxlength="2000" placeholder="What would you like to know?"></textarea><button class="btn small" type="submit">Send Question</button></form></section>
<section class="card"><span class="badge">SHARE WHAT YOU KNOW</span><h2>📝 Contribute Knowledge</h2><p>Share an additional story, observation, source, or documentation. Contributions are reviewed before becoming official archive knowledge.</p><form method="post" enctype="multipart/form-data" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="contribution"><input class="input" name="visitor_name" required maxlength="120" placeholder="Your name / nickname"><input class="input" name="title" required maxlength="180" placeholder="Contribution title"><textarea name="content" rows="5" required maxlength="5000" placeholder="What knowledge would you like to share?"></textarea><input class="input" name="source" maxlength="255" placeholder="Source / reference (optional)"><input class="input" type="file" name="image" accept="image/jpeg,image/png,image/webp"><button class="btn small" type="submit">Submit Knowledge</button></form></section></div>
<section class="card" style="margin-top:18px"><div class="section-kicker">💡 Community Answers</div><h2>Answered Questions</h2><div class="community-answer-list"><?php foreach($qs as $q): ?><article class="answer-card"><b>Q: <?=e($q['question'])?></b><p><?=nl2br(e($q['answer']))?></p><small>Asked by <?=e($q['visitor_name'])?> · Answered <?=e($q['answered_at'])?></small></article><?php endforeach; if(!$qs): ?><div class="empty compact"><p>No answered questions yet.</p></div><?php endif; ?></div></section>
<section class="card" style="margin-top:18px"><div class="section-kicker">📝 COMMUNITY CONTRIBUTIONS</div><h2>Shared Knowledge</h2><p>Contributions shown here have been reviewed and approved by the administrator.</p><div class="community-answer-list"><?php foreach($contributions as $c): ?><article class="answer-card"><?php if(!empty($c['image_path'])): ?><img class="media" src="<?=e(media_url($c['image_path']))?>" alt="<?=e($c['title'])?>" loading="lazy"><?php endif; ?><h3><?=e($c['title'])?></h3><p><?=nl2br(e($c['content']))?></p><small>Shared by <?=e($c['visitor_name'])?><?php if(!empty($c['source'])): ?> · Source: <?=e($c['source'])?><?php endif; ?></small></article><?php endforeach; if(!$contributions): ?><div class="empty compact"><p>No approved community contributions yet.</p></div><?php endif; ?></div></section>
<?php include 'partials/footer.php'; ?>